import{c as r,$ as s,Q as t,j as i,m as o,h as l,ax as a,n as h,o as d,S as c}from"./chunks/framework.BqPkuuVc.js";const k=JSON.parse('{"title":"Download, install and update","description":"","frontmatter":{},"headers":[],"relativePath":"user/download-and-install/index.md","filePath":"user/download-and-install/index.md"}'),u={name:"user/download-and-install/index.md"};function p(g,e,m,b,w,f){const n=s("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o('<h1 id="download-install-and-update" tabindex="-1">Download, install and update <a class="header-anchor" href="#download-install-and-update" aria-label="Permalink to &quot;Download, install and update&quot;">​</a></h1><p><strong>Audience:</strong> Anyone setting up Manager on a computer for the first time, or keeping an existing install up to date.</p><p>How to obtain meshO Manager, install it on Windows, Mac or Linux, run it from the system tray or menu bar, open it on other devices, and keep it updated.</p><h2 id="install-on-one-machine-only" tabindex="-1">Install on one machine only <a class="header-anchor" href="#install-on-one-machine-only" aria-label="Permalink to &quot;Install on one machine only&quot;">​</a></h2><p>Before you start, the most important thing to understand:</p><blockquote><p><strong>You only install Manager on one computer per event.</strong> Every other device — registration laptops, the download desk, leaderboard TVs, commentators&#39; tablets, spectators&#39; phones — connects to that one machine through a web browser. Nothing to install on them. No accounts to create. They just open a URL.</p></blockquote>',6)),(t(),l(c,null,{default:a(()=>[d(n,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20install%5B%22Install%20Manager%20here%22%5D%0A%20%20%20%20%20%20%20%20server(%5B%22meshO%20Manager%20Server%22%5D)%0A%20%20%20%20end%0A%20%20%20%20server%20---%20rego%5B%22Registration%20laptop%3Cbr%2F%3E(browser)%22%5D%0A%20%20%20%20server%20---%20download%5B%22Download%20desk%3Cbr%2F%3E(browser)%22%5D%0A%20%20%20%20server%20---%20tv%5B%22Leaderboard%20TV%3Cbr%2F%3E(browser)%22%5D%0A%20%20%20%20server%20---%20phone%5B%22Spectator%20phone%3Cbr%2F%3E(browser)%22%5D%0A%20%20%20%20style%20server%20fill%3A%23FF914D%2Ccolor%3A%23000000%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>Pick whichever computer you&#39;d like to act as the <strong>server</strong> — your registration PC, your download PC, or a dedicated machine. As long as the other devices can reach it on the local network, it works. See <a href="./../what-is-mesho-manager/">How meshO Manager works</a> for the architecture in more detail.</p><h3 id="one-exception-mesho-prime-must-plug-into-the-server" tabindex="-1">One exception: meshO Prime must plug into the server <a class="header-anchor" href="#one-exception-mesho-prime-must-plug-into-the-server" aria-label="Permalink to &quot;One exception: meshO Prime must plug into the server&quot;">​</a></h3><p>There&#39;s a single piece of hardware that has to be physically connected to the <strong>server</strong> computer rather than any of the browser-only devices: the <strong>meshO Prime field unit</strong> that receives radio punches from the controls in the forest.</p><p>Prime connects to the server over USB (serial) and the <strong>server process</strong> is what reads from it. Browsers can&#39;t talk to Prime — they only display what the server has already received.</p><p>So when you pick which computer to install Manager on, make sure it has a free USB port for the Prime field unit.</p><p>Everything else — SportIdent download units, leaderboard TVs, registration laptops — can be on any device because those run through the browser. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a> for the full setup.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><ul><li><strong>Windows 10 or 11</strong> (64-bit), or</li><li><strong>macOS 12 (Monterey) or later</strong> — both Apple Silicon (M1/M2/M3/M4) and Intel are supported, or</li><li><strong>Linux</strong> (64-bit, x86_64) — distributed as an AppImage that runs on most modern distributions.</li><li>A local network the other event devices can reach (Wi-Fi or wired). The server doesn&#39;t need an internet connection during the event — it&#39;s only required for downloading updates.</li></ul><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Pick the file that matches your computer. These links always download the <strong>latest version</strong>:</p><table tabindex="0"><thead><tr><th>Computer</th><th>Download</th></tr></thead><tbody><tr><td>Windows PC</td><td><a href="https://github.com/mesho-live/manager-releases/releases/latest/download/meshOManager-latest-win-x64-setup.exe" target="_blank" rel="noreferrer"><strong>Download for Windows</strong></a> (<code>.exe</code> installer)</td></tr><tr><td>Mac with Apple Silicon (M1/M2/M3/M4)</td><td><a href="https://github.com/mesho-live/manager-releases/releases/latest/download/meshOManager-latest-osx-arm64.dmg" target="_blank" rel="noreferrer"><strong>Download for Apple Silicon Mac</strong></a> (<code>.dmg</code>)</td></tr><tr><td>Intel-based Mac</td><td><a href="https://github.com/mesho-live/manager-releases/releases/latest/download/meshOManager-latest-osx-x64.dmg" target="_blank" rel="noreferrer"><strong>Download for Intel Mac</strong></a> (<code>.dmg</code>)</td></tr><tr><td>Linux PC (64-bit)</td><td><a href="https://github.com/mesho-live/manager-releases/releases/latest/download/meshOManager-latest-linux-x64.AppImage" target="_blank" rel="noreferrer"><strong>Download for Linux</strong></a> (<code>.AppImage</code>)</td></tr></tbody></table><blockquote><p><strong>Not sure which Mac you have?</strong> Click the Apple menu → <strong>About This Mac</strong>. If the <strong>Chip</strong> line says &quot;Apple M1&quot; / &quot;M2&quot; / &quot;M3&quot; / &quot;M4&quot;, choose the <strong>Apple Silicon</strong> download. If it says &quot;Intel&quot;, choose the <strong>Intel</strong> download.</p></blockquote><blockquote><p><strong>The downloaded file is named <code>meshOManager-latest-…</code></strong> rather than carrying a version number — that&#39;s expected for these always-current links. The actual version is baked into the app; check it any time via <strong>Tray / menu bar icon → About</strong>.</p></blockquote><h2 id="install-on-windows" tabindex="-1">Install on Windows <a class="header-anchor" href="#install-on-windows" aria-label="Permalink to &quot;Install on Windows&quot;">​</a></h2><ol><li>Run the installer you downloaded (<code>meshOManager-latest-win-x64-setup.exe</code>).</li><li><strong>Work around the browser and SmartScreen warnings</strong> — see <a href="#allowing-the-install-on-windows">Allowing the install on Windows</a> below. Manager is currently distributed without a Microsoft-recognised code-signing certificate, so Windows will warn you about it the first time you install or run it.</li><li>The installer is a <strong>per-user install</strong> — there&#39;s no UAC / admin prompt. Manager is installed under your user account at <code>%LOCALAPPDATA%\\Programs\\meshO Manager</code>.</li><li>Accept the default install location (recommended) or change it.</li><li>Click <strong>Install</strong>.</li><li>On the final page, leave <strong>Launch meshO Manager now</strong> ticked and click <strong>Finish</strong>.</li></ol><p>The installer creates:</p><ul><li>A <strong>Start Menu</strong> entry under &quot;meshO Manager&quot;</li><li>A <strong>desktop shortcut</strong></li></ul><p>Both shortcuts launch the tray app, not the server directly — see <a href="#the-tray-icon-windows">The tray icon (Windows)</a> below.</p><h3 id="allowing-the-install-on-windows" tabindex="-1">Allowing the install on Windows <a class="header-anchor" href="#allowing-the-install-on-windows" aria-label="Permalink to &quot;Allowing the install on Windows&quot;">​</a></h3><p>Until Manager ships with a code-signing certificate that Microsoft recognises, you&#39;ll have to click past two or three &quot;are you sure?&quot; prompts during install. None of them indicate a real problem — they just mean Microsoft hasn&#39;t seen this exact file enough times yet to vouch for it.</p><p><strong>1. Browser download warning.</strong> Chrome and Edge may flag the <code>setup.exe</code> as &quot;not commonly downloaded&quot; and refuse to save it.</p><ul><li><strong>Edge:</strong> click the <strong>⋯</strong> next to the blocked download → <strong>Keep</strong> → confirm <strong>Keep anyway</strong>.</li><li><strong>Chrome:</strong> click the <strong>⋮</strong> next to the blocked download → <strong>Keep</strong>.</li></ul><p><strong>2. Windows SmartScreen — &quot;Windows protected your PC&quot;.</strong> When you run the installer, a blue dialog may appear: <em>&quot;Microsoft Defender SmartScreen prevented an unrecognised app from starting.&quot;</em></p><ul><li>Click <strong>More info</strong> (the small link below the message).</li><li>A <strong>Run anyway</strong> button appears — click it.</li></ul><p><strong>3. Antivirus quarantine.</strong> Some third-party antivirus products will quarantine the installer or the installed <code>meshOManagerServer.exe</code> because it&#39;s an unsigned executable that listens on a network port. If Manager fails to start after install, check your antivirus&#39;s quarantine list and add an exclusion for the install folder (<code>%LOCALAPPDATA%\\Programs\\meshO Manager</code>).</p><h2 id="install-on-macos" tabindex="-1">Install on macOS <a class="header-anchor" href="#install-on-macos" aria-label="Permalink to &quot;Install on macOS&quot;">​</a></h2><ol><li>Double-click the downloaded <code>.dmg</code>. Finder mounts it and opens a window showing <strong>meshO Manager.app</strong> next to an <strong>Applications</strong> shortcut.</li><li>Drag <strong>meshO Manager.app</strong> onto the <strong>Applications</strong> shortcut to copy it across.</li><li>Eject the disk image — drag its icon to the Trash, or click the <strong>⏏</strong> next to its entry in the Finder sidebar.</li><li>Open <strong>Applications</strong> and launch <strong>meshO Manager</strong> for the first time.</li><li><strong>Work around Gatekeeper</strong> — macOS blocks the first launch because Manager isn&#39;t notarised by Apple yet. Which message you see, and how to clear it, depends on your Mac — see <a href="#allowing-the-app-on-macos">Allowing the app on macOS</a> below.</li><li>Once you&#39;ve allowed it, the app launches into the menu bar — see <a href="#the-menu-bar-icon-macos">The menu bar icon (macOS)</a> below.</li></ol><h3 id="allowing-the-app-on-macos" tabindex="-1">Allowing the app on macOS <a class="header-anchor" href="#allowing-the-app-on-macos" aria-label="Permalink to &quot;Allowing the app on macOS&quot;">​</a></h3><p>Manager isn&#39;t notarised by Apple yet, so macOS blocks it the first time you launch it. <strong>This is expected and does not mean anything is wrong with the download</strong> — you just need to clear the block once. After the first successful launch, macOS remembers your decision and Manager opens normally from then on (including auto-updates).</p><p>The exact message you get depends on your Mac, so <strong>follow the section that matches what you see</strong>:</p><h4 id="is-damaged-and-can-t-be-opened-you-should-move-it-to-the-bin-trash" tabindex="-1">&quot;…is damaged and can&#39;t be opened. You should move it to the Bin/Trash.&quot; <a class="header-anchor" href="#is-damaged-and-can-t-be-opened-you-should-move-it-to-the-bin-trash" aria-label="Permalink to &quot;&quot;…is damaged and can&#39;t be opened. You should move it to the Bin/Trash.&quot;&quot;">​</a></h4><p>This is the most common message, especially on <strong>Apple Silicon Macs (M1/M2/M3/M4)</strong>. Despite the wording, <strong>the app is <em>not</em> damaged</strong> — macOS shows this because your browser tagged the download with a &quot;quarantine&quot; flag and Manager isn&#39;t notarised. <strong>Do not move it to the Bin.</strong></p><p>The one reliable fix is to strip the quarantine flag from <strong>Terminal</strong>. Open <strong>Terminal</strong> (Applications → Utilities → Terminal, or press <code>⌘+Space</code> and type &quot;Terminal&quot;), then paste this line and press Return:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/meshO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Manager.app</span></span></code></pre></div><p>Then launch <strong>meshO Manager</strong> normally from Applications. That&#39;s it — the command only removes the quarantine flag; the app itself is untouched.</p><blockquote><p><strong>Right-click → Open does <em>not</em> clear the &quot;damaged&quot; message</strong> on Apple Silicon — only the Terminal command above does. If you tried right-clicking first and it still refused, that&#39;s expected; run the command and you&#39;re set.</p></blockquote><h4 id="can-t-be-opened-because-it-is-from-an-unidentified-developer-apple-could-not-verify" tabindex="-1">&quot;…can&#39;t be opened because it is from an unidentified developer&quot; / &quot;Apple could not verify…&quot; <a class="header-anchor" href="#can-t-be-opened-because-it-is-from-an-unidentified-developer-apple-could-not-verify" aria-label="Permalink to &quot;&quot;…can&#39;t be opened because it is from an unidentified developer&quot; / &quot;Apple could not verify…&quot;&quot;">​</a></h4><p>You&#39;ll usually see this milder message on <strong>Intel Macs</strong>. Here you have two options — either works:</p><p><strong>Option A — Right-click → Open.</strong> In the <strong>Applications</strong> folder, right-click (or Control-click) <strong>meshO Manager.app</strong> and choose <strong>Open</strong>. A dialog appears warning that the developer can&#39;t be verified — click <strong>Open</strong> to confirm. <em>Double-clicking the app instead of right-clicking won&#39;t show the Open button — it just blocks.</em></p><p><strong>Option B — Approve from System Settings.</strong> If the right-click dialog only offers <strong>Cancel</strong> (no <strong>Open</strong>):</p><ul><li>Open <strong>System Settings → Privacy &amp; Security</strong>.</li><li>Scroll to the <strong>Security</strong> section. You should see a message: <em>&quot;meshO Manager.app was blocked from use because it is not from an identified developer.&quot;</em></li><li>Click <strong>Open Anyway</strong> next to that message.</li><li>Authenticate with Touch ID or your password if prompted.</li><li>Launch the app again — this time a dialog will offer an <strong>Open</strong> button. Click it.</li></ul><blockquote><p>If Option A or B doesn&#39;t clear it, fall back to the Terminal command from the &quot;damaged&quot; section above — <code>xattr -cr /Applications/meshO\\ Manager.app</code> clears the block regardless of which message you saw.</p></blockquote><blockquote><p><strong>Why does this happen?</strong> Apple requires developers to submit each app build to its <strong>notarisation</strong> service, which scans for malware and signs the result. Manager isn&#39;t put through that process yet, so macOS treats it as coming from an unidentified developer and blocks the quarantined download. Notarisation is on the roadmap and will remove these steps for future versions. It is <strong>not</strong> related to which browser you used — Safari, Chrome and Edge all tag downloads with the same quarantine flag.</p></blockquote><blockquote><p><strong>Downloading cards on this Mac?</strong> One more one-time step, unrelated to Gatekeeper: macOS doesn&#39;t recognise SportIdent&#39;s USB stations, so the browser can&#39;t see your reader until you install the Silicon Labs CP210x driver. See <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>. You don&#39;t need it if this Mac is only the server and cards are downloaded elsewhere.</p></blockquote><h2 id="install-on-linux" tabindex="-1">Install on Linux <a class="header-anchor" href="#install-on-linux" aria-label="Permalink to &quot;Install on Linux&quot;">​</a></h2><p>The Linux build is distributed as an <strong>AppImage</strong> — a single self-contained file you can run from anywhere, with nothing to install system-wide.</p><ol><li><p>Download the AppImage (<code>meshOManager-latest-linux-x64.AppImage</code>) using the link above.</p></li><li><p>Make it executable — either in your file manager (Properties → Permissions → &quot;Allow executing file as program&quot;) or from a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meshOManager-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-linux-x64.AppImage</span></span></code></pre></div></li><li><p>Run it — double-click in your file manager, or from a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./meshOManager-*-linux-x64.AppImage</span></span></code></pre></div></li></ol><p>Your browser opens automatically to <code>http://localhost:5154/manager</code> once the server is up. If nothing opens (for example on a minimal install with no <code>xdg-open</code> or <code>google-chrome</code> on the <code>PATH</code>), open that URL yourself.</p><blockquote><p><strong>No tray icon yet.</strong> Unlike Windows and macOS, the Linux build does <strong>not</strong> add a system-tray/menu-bar icon in this version. The AppImage runs the server directly in the foreground:</p><ul><li>Started <strong>from a terminal</strong>, the server logs to that terminal; press <code>Ctrl+C</code> there to stop it.</li><li>Started by <strong>double-clicking</strong>, it runs in the background with no window. Quit it from your system monitor, or from a terminal with <code>pkill -f meshOManager</code> / <code>pkill -f meshOManagerServer</code>.</li></ul><p>A proper tray launcher (matching Windows/macOS) is on the roadmap.</p></blockquote><blockquote><p><strong>FUSE requirement.</strong> AppImages need FUSE to mount themselves. Most desktop distributions ship it; if you see an error like <em>&quot;dlopen(): error loading libfuse.so.2&quot;</em>, either install your distro&#39;s FUSE 2 package (e.g. <code>sudo apt install libfuse2</code> on Debian/Ubuntu) or run the AppImage with the <code>--appimage-extract-and-run</code> flag, or use the <code>linux-x64.zip</code> portable folder instead.</p></blockquote><h2 id="how-the-server-runs-in-the-background" tabindex="-1">How the server runs in the background <a class="header-anchor" href="#how-the-server-runs-in-the-background" aria-label="Permalink to &quot;How the server runs in the background&quot;">​</a></h2><p>Manager is split into two pieces:</p><ul><li><strong>The server</strong> — the background process that holds your event data, receives radio punches from a connected meshO Prime field unit, and serves the web UI.</li><li><strong>A small tray / menu bar app</strong> that starts the server, keeps an icon visible so you can interact with it, and shuts the server down cleanly when you quit.</li></ul><p>SportIdent USB reader stations (BSM7-USB / BSM8-USB) are <strong>not</strong> handled by the server. They&#39;re read directly by the browser on whichever device runs the download desk, using the browser&#39;s built-in Web Serial support, and the downloads are sent up to the server from there. That&#39;s why your download desk can be a different computer to the server — the SportIdent reader plugs into the download laptop, not the server. (meshO Prime, on the other hand, <em>does</em> plug into the server — see above.)</p><p>You never see a console window or a main app window. The server runs silently in the background; everything you see is in a browser tab.</p><p>When the tray / menu bar app starts:</p><ol><li>It launches the server as a child process.</li><li>The server binds to port <code>5154</code> by default and starts serving the web UI.</li><li>Your default browser opens automatically to <code>http://localhost:5154/manager</code>.</li><li>The tray / menu bar icon stays visible so you can re-open the browser, find your data files, read the documentation, or quit.</li></ol><blockquote><p><strong>Tip:</strong> If you have Google Chrome installed, Manager will use it. Chrome is the browser the UI is developed and tested against, so it tends to give the best results. Other browsers also work.</p></blockquote><blockquote><p><strong>On the server machine, use <code>localhost</code>.</strong> When you&#39;re working on the computer that runs the server, always reach Manager at <code>http://localhost:5154/manager</code> — that&#39;s what the tray / menu bar app opens for you. It&#39;s the preferred address rather than the machine&#39;s host name or IP: it&#39;s shorter, it always works regardless of which network the computer is on, and <code>localhost</code> is automatically a secure context so <a href="./../running-the-event/card-download">card download</a> works without any HTTPS setup. Save the IP address for the <em>other</em> devices (see <a href="#opening-manager-on-other-devices">below</a>).</p></blockquote><blockquote><p><strong>The documentation works offline.</strong> The <strong>Documentation</strong> item in the tray / menu bar opens the copy that ships inside Manager itself, served at <code>http://localhost:5154/docs/</code> alongside Manager — so it&#39;s there at an event with no internet, and it matches the version you have installed. The same pages are online at <a href="https://docs.mesho.live" target="_blank" rel="noreferrer">docs.mesho.live</a> if you&#39;d rather read them on another device.</p></blockquote><h3 id="the-tray-icon-windows" tabindex="-1">The tray icon (Windows) <a class="header-anchor" href="#the-tray-icon-windows" aria-label="Permalink to &quot;The tray icon (Windows)&quot;">​</a></h3><p>After install, look for the <strong>meshO</strong> icon in the <strong>system tray</strong> (bottom-right of the taskbar, near the clock). You may need to click the <strong>^</strong> arrow to see hidden icons.</p><p>Available actions:</p><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td><strong>Open Manager in browser</strong></td><td>Double-click the tray icon, or right-click → <strong>Open</strong> (or <code>Ctrl+O</code> while the menu is open)</td></tr><tr><td><strong>Find your event files in Explorer</strong></td><td>Right-click → <strong>Show Files in Explorer</strong></td></tr><tr><td><strong>Read the documentation</strong></td><td>Right-click → <strong>Documentation</strong></td></tr><tr><td><strong>See the installed version</strong></td><td>Right-click → <strong>About</strong></td></tr><tr><td><strong>Quit (also stops the server)</strong></td><td>Right-click → <strong>Quit</strong> (or <code>Ctrl+Q</code> while the menu is open)</td></tr></tbody></table><h3 id="the-menu-bar-icon-macos" tabindex="-1">The menu bar icon (macOS) <a class="header-anchor" href="#the-menu-bar-icon-macos" aria-label="Permalink to &quot;The menu bar icon (macOS)&quot;">​</a></h3><p>After launch, look for the <strong>meshO</strong> icon in the <strong>menu bar</strong> at the top-right of the screen.</p><p>Available actions:</p><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td><strong>Open Manager in browser</strong></td><td>Click the menu bar icon → <strong>Open</strong> (or <code>⌘O</code> while the menu is open)</td></tr><tr><td><strong>Re-open Manager after closing the browser tab</strong></td><td>Click the menu bar icon → <strong>Open</strong>, or simply launch <strong>meshO Manager</strong> again from Applications, the Dock or Spotlight</td></tr><tr><td><strong>Find your event files in Finder</strong></td><td>Click the menu bar icon → <strong>Show Files in Finder</strong></td></tr><tr><td><strong>Read the documentation</strong></td><td>Click the menu bar icon → <strong>Documentation</strong></td></tr><tr><td><strong>See the installed version</strong></td><td>Click the menu bar icon → <strong>About</strong></td></tr><tr><td><strong>Quit (also stops the server)</strong></td><td>Click the menu bar icon → <strong>Quit</strong> (or <code>⌘Q</code> while the menu is open)</td></tr></tbody></table><p>Manager doesn&#39;t appear in the Dock or <code>⌘+Tab</code> switcher by design — it&#39;s a background app, controlled from the menu bar. Launching it again while it&#39;s already running doesn&#39;t start a second copy: it re-opens Manager in your browser, exactly as <strong>Open</strong> does.</p><h2 id="opening-manager-on-other-devices" tabindex="-1">Opening Manager on other devices <a class="header-anchor" href="#opening-manager-on-other-devices" aria-label="Permalink to &quot;Opening Manager on other devices&quot;">​</a></h2><p>The other devices at your event — laptops, tablets, phones, TVs — connect to the server over your local network.</p><h3 id="_1-find-the-server-s-ip-address" tabindex="-1">1. Find the server&#39;s IP address <a class="header-anchor" href="#_1-find-the-server-s-ip-address" aria-label="Permalink to &quot;1. Find the server&#39;s IP address&quot;">​</a></h3><p>On the server PC, find its local IP address:</p><ul><li><strong>Windows:</strong> open Command Prompt and run <code>ipconfig</code>. Look for an <strong>IPv4 Address</strong> under your active network adapter (e.g. <code>192.168.1.42</code>).</li><li><strong>macOS:</strong> open <strong>System Settings → Network</strong>, click your active connection, and read the <strong>IP address</strong> at the top.</li></ul><h3 id="_2-open-the-url-on-the-other-device" tabindex="-1">2. Open the URL on the other device <a class="header-anchor" href="#_2-open-the-url-on-the-other-device" aria-label="Permalink to &quot;2. Open the URL on the other device&quot;">​</a></h3><p>On the other device, open a web browser and navigate to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server-ip&gt;:5154/manager</span></span></code></pre></div><p>For example: <code>http://192.168.1.42:5154/manager</code>.</p><p>That&#39;s it — no install, no login. The page loads the full Manager UI and stays in sync in real time with everyone else.</p><blockquote><p><strong>Tip:</strong> Bookmark the URL on each device, or save it as a Home Screen shortcut on phones and tablets, so volunteers can re-open it with one tap on event day.</p></blockquote><h3 id="different-port" tabindex="-1">Different port? <a class="header-anchor" href="#different-port" aria-label="Permalink to &quot;Different port?&quot;">​</a></h3><p>If you&#39;ve changed <strong>Server.Port</strong> in <a href="./../reference/settings">Settings → Server</a>, use that port number instead of <code>5154</code> in the URL.</p><h3 id="firewall-prompt-on-first-launch" tabindex="-1">Firewall prompt on first launch <a class="header-anchor" href="#firewall-prompt-on-first-launch" aria-label="Permalink to &quot;Firewall prompt on first launch&quot;">​</a></h3><p>Windows may show a <strong>Windows Defender Firewall</strong> prompt the first time the server starts, asking whether to allow Manager to communicate on private and public networks. Tick <strong>Private networks</strong> and click <strong>Allow access</strong> — without it, other devices on the network can&#39;t reach the server.</p><h2 id="quitting-manager" tabindex="-1">Quitting Manager <a class="header-anchor" href="#quitting-manager" aria-label="Permalink to &quot;Quitting Manager&quot;">​</a></h2><p>Quit through the tray / menu bar icon:</p><ul><li><strong>Windows:</strong> right-click the tray icon → <strong>Quit</strong>.</li><li><strong>macOS:</strong> click the menu bar icon → <strong>Quit</strong>.</li></ul><p>This shuts down the server cleanly. Closing the browser tab on its own <strong>does not</strong> stop the server — the server keeps running in the background until you quit from the tray / menu bar.</p><blockquote><p><strong>Tip:</strong> You don&#39;t have to quit between events. Manager is happy sitting in the tray / menu bar indefinitely — leave it running and it&#39;ll be there for the next event with all your previous events still loaded. Many users just leave it running all the time.</p></blockquote><blockquote><p><strong>Warning:</strong> Don&#39;t shut down the server PC mid-event. The server flushes event data to disk continuously, but a sudden power-off can still cost you the last few seconds of in-flight data. Always quit Manager first, or use the OS shutdown command (which gives Manager a chance to exit cleanly).</p></blockquote><h2 id="re-launching" tabindex="-1">Re-launching <a class="header-anchor" href="#re-launching" aria-label="Permalink to &quot;Re-launching&quot;">​</a></h2><ul><li><strong>Windows:</strong> open the <strong>Start Menu</strong> and search for &quot;meshO Manager&quot;, or use the desktop shortcut.</li><li><strong>macOS:</strong> open <strong>Applications → meshO Manager</strong>, or launch it from Spotlight (<code>⌘+Space</code>, type &quot;meshO&quot;).</li></ul><p>Manager re-opens silently into the tray / menu bar and reopens your browser to the events page. Your previous events, settings, and downloads are all preserved — they live in a separate folder from the application itself (see <a href="#where-your-data-is-stored">Where your data is stored</a>).</p><h3 id="launching-at-login" tabindex="-1">Launching at login <a class="header-anchor" href="#launching-at-login" aria-label="Permalink to &quot;Launching at login&quot;">​</a></h3><p>If you want Manager to start automatically when you log in:</p><ul><li><strong>Windows:</strong> drop a shortcut to <strong>meshO Manager</strong> into <code>shell:startup</code> (open File Explorer, type <code>shell:startup</code> in the address bar, then drag the desktop shortcut in).</li><li><strong>macOS:</strong> open <strong>System Settings → General → Login Items</strong>, click <strong>+</strong> under &quot;Open at Login&quot;, and add <strong>meshO Manager.app</strong>.</li></ul><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>Manager checks for new versions in the background and tells you when one is available. You can apply updates manually, or let Manager apply them automatically when nothing&#39;s going on.</p><h3 id="when-a-new-version-is-available" tabindex="-1">When a new version is available <a class="header-anchor" href="#when-a-new-version-is-available" aria-label="Permalink to &quot;When a new version is available&quot;">​</a></h3><p>A notification appears in the bottom-right corner of the Manager UI:</p><blockquote><p>A new version (X) is available. Your current version is Y.</p></blockquote><p>The notification has three buttons:</p><ul><li><strong>Update Now</strong> — downloads and installs the new version immediately. The server stops, replaces itself, and restarts. The browser page reloads automatically once the new server is ready (usually 10–30 seconds).</li><li><strong>Release Notes</strong> — opens the GitHub release page in a new tab so you can see what changed.</li><li><strong>Dismiss</strong> — hides the notification for this browser session. It&#39;ll come back next time you reload, or when an even newer version is released.</li></ul><blockquote><p><strong>Tip:</strong> The update notification is automatically <strong>hidden while a live event is running</strong>, so an installer banner can&#39;t distract a timing operator. Updates resume showing once the event is finished.</p></blockquote><h3 id="automatic-updates" tabindex="-1">Automatic updates <a class="header-anchor" href="#automatic-updates" aria-label="Permalink to &quot;Automatic updates&quot;">​</a></h3><p>If you&#39;d rather not think about it, turn on <strong>automatic updates</strong>:</p><ol><li>Open <strong>Settings → Auto Update</strong>.</li><li>Turn on <strong>Automatically install updates</strong>.</li></ol><p>With auto-update on, the server checks for new versions every 30 minutes and applies them when <strong>all</strong> of these are true:</p><ul><li>No event is currently in progress.</li><li>No browser tab is connected to Manager.</li></ul><p>Those two guards mean an auto-update never interrupts an active event, and never yanks the page out from under you mid-session. If either guard fails, the update is deferred — auto-update will simply try again at the next check.</p><p>If an event is active or browsers are connected, the notification banner appears instead and you choose when to apply the update.</p><h3 id="manual-check-for-updates" tabindex="-1">Manual check for updates <a class="header-anchor" href="#manual-check-for-updates" aria-label="Permalink to &quot;Manual check for updates&quot;">​</a></h3><p>You can also force a check at any time:</p><ol><li>Open <strong>Settings → Auto Update</strong>.</li><li>Click <strong>Check for Updates</strong>.</li></ol><p>If a newer version exists, an <strong>Update Now</strong> button appears next to the result. Click it to apply the update immediately.</p><h3 id="installing-an-update-manually" tabindex="-1">Installing an update manually <a class="header-anchor" href="#installing-an-update-manually" aria-label="Permalink to &quot;Installing an update manually&quot;">​</a></h3><p>If you&#39;d rather install updates by hand turn off <strong>Automatically install updates</strong> and download a new installer the same way you did for a fresh install — use the <a href="#download">direct download links</a> above.</p><ul><li><strong>Windows:</strong> run the new <code>setup.exe</code> and let it install over the existing version — the installer closes a running Manager for you before it copies files, so you don&#39;t need to quit it from the tray first. You&#39;ll see the same SmartScreen and browser warnings as the original install — clear them the same way (see <a href="#allowing-the-install-on-windows">Allowing the install on Windows</a>).</li><li><strong>macOS:</strong> quit Manager from the menu bar, mount the new <code>.dmg</code>, and drag <strong>meshO Manager.app</strong> onto the <strong>Applications</strong> shortcut, choosing <strong>Replace</strong> when prompted. Because the new download carries a fresh quarantine attribute, Gatekeeper will block the first launch of the replacement — clear it the same way (see <a href="#allowing-the-app-on-macos">Allowing the app on macOS</a>).</li><li><strong>Linux:</strong> stop the running server, download the new <code>.AppImage</code>, make it executable (<code>chmod +x</code>), and replace the old file. <strong>Linux updates are always manual</strong> — the in-app updater is disabled on the AppImage because it can&#39;t modify the read-only AppImage file, so you won&#39;t get a one-click &quot;Update Now&quot; there. Your events and settings are preserved across the swap (they live in <code>~/.local/share/meshO Manager</code>, separate from the AppImage).</li></ul><p>Your events, settings, and downloads are kept across the upgrade.</p><blockquote><p><strong>Auto-updates don&#39;t hit these warnings.</strong> When <strong>Automatically install updates</strong> is on, the in-app updater downloads new versions directly (not through your browser, so no quarantine attribute on macOS) and on macOS it ad-hoc re-signs the new bundle and clears the quarantine flag for you. There&#39;s nothing to click past.</p></blockquote><h2 id="where-your-data-is-stored" tabindex="-1">Where your data is stored <a class="header-anchor" href="#where-your-data-is-stored" aria-label="Permalink to &quot;Where your data is stored&quot;">​</a></h2><p>Manager keeps <strong>application files</strong> (the program itself) and <strong>your data</strong> (events, settings, logs) in separate places. Uninstalling or upgrading Manager only touches the application files — your data is preserved.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ul><li><strong>Application files:</strong> <code>%LOCALAPPDATA%\\Programs\\meshO Manager</code> (e.g. <code>C:\\Users\\&lt;you&gt;\\AppData\\Local\\Programs\\meshO Manager</code>).</li><li><strong>Settings, logs and runtime state:</strong> <code>%LOCALAPPDATA%\\meshO Manager</code>.</li><li><strong>Events and downloads:</strong> <code>C:\\Users\\Public\\Documents\\meshO Manager</code> — shared across users on the machine.</li></ul><p>The fastest way to find your event files is <strong>Tray icon → Show Files in Explorer</strong>.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><ul><li><strong>Application:</strong> <code>/Applications/meshO Manager.app</code>.</li><li><strong>Events, settings, logs and downloads:</strong> <code>~/Library/Application Support/meshO Manager</code>.</li></ul><p>The fastest way to find your event files is <strong>Menu bar icon → Show Files in Finder</strong>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><ul><li><strong>Application:</strong> wherever you saved the <code>.AppImage</code> (it&#39;s a single self-contained file — nothing is installed elsewhere).</li><li><strong>Events, settings, logs and downloads:</strong> <code>~/.local/share/meshO Manager</code> (or <code>$XDG_DATA_HOME/meshO Manager</code> if you&#39;ve set <code>XDG_DATA_HOME</code>).</li></ul><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><h3 id="windows-1" tabindex="-1">Windows <a class="header-anchor" href="#windows-1" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Quit Manager from the tray icon.</li><li>Open <strong>Settings → Apps → Installed apps</strong>, find <strong>meshO Manager</strong>, and choose <strong>Uninstall</strong>.</li></ol><p>Your data folders (<code>%LOCALAPPDATA%\\meshO Manager</code> and <code>Public\\Documents\\meshO Manager</code>) are intentionally <strong>left in place</strong> so you don&#39;t lose events if you reinstall later. Delete them manually if you want them gone.</p><h3 id="macos-1" tabindex="-1">macOS <a class="header-anchor" href="#macos-1" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><ol><li>Quit Manager from the menu bar icon.</li><li>Drag <strong>meshO Manager.app</strong> from <strong>Applications</strong> to the Trash.</li></ol><blockquote><p><strong>Quit it first.</strong> Skip step 1 and Finder refuses with <em>&quot;meshO Manager.app can&#39;t be moved to the Bin because it&#39;s open&quot;</em> — the server is still running in the background. Manager won&#39;t be listed in <strong>Force Quit Applications</strong> either: that window only lists apps with windows, never menu bar apps. Click the <strong>meshO</strong> menu bar icon → <strong>Quit</strong>, then drag it to the Trash.</p></blockquote><p>Your data folder (<code>~/Library/Application Support/meshO Manager</code>) is left in place. Delete it manually if you want a clean slate.</p><h3 id="linux-1" tabindex="-1">Linux <a class="header-anchor" href="#linux-1" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><ol><li>Stop the server (see <a href="#install-on-linux">No tray icon yet</a> — <code>Ctrl+C</code> in its terminal, or <code>pkill -f meshOManagerServer</code>).</li><li>Delete the <code>.AppImage</code> file.</li></ol><p>Your data folder (<code>~/.local/share/meshO Manager</code>) is left in place. Delete it manually if you want a clean slate.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">How meshO Manager works</a> — the one-server, many-browsers architecture in more detail.</li><li><a href="./../getting-started/first-event-walkthrough">Walkthrough: your first event</a> — what to do once Manager is installed.</li><li><a href="./../reference/multi-operator-setup">Multi-operator setup</a> — patterns for running several operators against one server.</li><li><a href="./../reference/settings">Settings</a> — auto-update, server port, and other options.</li><li><a href="./../reference/troubleshooting">Troubleshooting</a> — what to do when something doesn&#39;t start.</li></ul>',143))])}const v=r(u,[["render",p]]);export{k as __pageData,v as default};
